package com.airesumebuilder.feature.notification.controller;import com.airesumebuilder.common.dto.ApiResponse;import com.airesumebuilder.feature.notification.service.NotificationService;import com.airesumebuilder.security.CurrentUser;import java.util.*;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/notifications")public class NotificationController{private final NotificationService s;private final CurrentUser u;public NotificationController(NotificationService s,CurrentUser u){this.s=s;this.u=u;}@GetMapping public ResponseEntity<ApiResponse<List<NotificationService.Item>>>list(@RequestParam(defaultValue="false")boolean unreadOnly){return ResponseEntity.ok(ApiResponse.success(s.list(u.email(),unreadOnly),"Notifications retrieved."));}@PatchMapping("/{id}/read")public ResponseEntity<ApiResponse<NotificationService.Item>>read(@PathVariable long id){return ResponseEntity.ok(ApiResponse.success(s.read(u.email(),id),"Notification read."));}@PatchMapping("/read-all")public ResponseEntity<ApiResponse<Map<String,Integer>>>all(){return ResponseEntity.ok(ApiResponse.success(Map.of("updated",s.readAll(u.email())),"Notifications read."));}@GetMapping("/preferences")public ResponseEntity<ApiResponse<NotificationService.Preferences>>preferences(){return ResponseEntity.ok(ApiResponse.success(s.preferences(u.email()),"Notification preferences retrieved."));}@PutMapping("/preferences")public ResponseEntity<ApiResponse<NotificationService.Preferences>>updatePreferences(@RequestBody NotificationService.Preferences preferences){return ResponseEntity.ok(ApiResponse.success(s.updatePreferences(u.email(),preferences),"Notification preferences updated."));}}
